use kimo_core::{color::shoulder,effects::{Frame,Params},keyframe::Prop};
#[test]fn monotonic_continuous_shoulder(){let k=0.75;let peak=1.;assert_eq!(shoulder::map(k,k,peak),k);assert!((shoulder::map(k+1e-6,k,peak)-k-1e-6).abs()<1e-10);let mut prev=-1.;for i in 0..10000{let v=shoulder::map(i as f64/100.,k,peak);assert!(v>=prev&&v<=peak);prev=v;}}
#[test]fn ratios_alpha_and_negative(){let mut f=Frame{w:2,h:1,d:vec![4.,2.,1.,0.5,-0.25,-0.5,-1.,1.]};shoulder::apply(&Params::new(),&mut f,0.).unwrap();assert!((f.d[0]/f.d[1]-2.).abs()<1e-6);assert!((f.d[1]/f.d[2]-2.).abs()<1e-6);assert_eq!(f.d[3],0.5);assert_eq!(f.d[4],-0.25);}
#[test]fn hostile_shoulder(){for(k,v)in[("gamut",99.),("peak",0.),("knee",-1.),("amount",2.)]{let mut p=Params::new();p.insert(k.into(),Prop::new(v));let mut f=Frame::new(1,1);assert!(shoulder::apply(&p,&mut f,0.).is_err());}}
#[test]fn managed_helper_guard(){use kimo_core::{commands::{Session,dispatch},render};use serde_json::json;let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","start":0,"duration":1})).unwrap()["clip_id"].clone();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":3}})).unwrap();let e=dispatch(&mut s,"add_managed_linear_effect",&json!({"clip_id":c,"kind":"luminance_shoulder","params":{"knee":0.75,"peak":1}})).unwrap();assert_eq!(e["working_gamut"],3);assert!(render::render_frame(&s.project,0.,&s.cache).is_ok());dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":0}})).unwrap();assert!(render::render_frame(&s.project,0.,&s.cache).is_err());assert!(dispatch(&mut s,"add_managed_linear_effect",&json!({"clip_id":c,"kind":"luminance_shoulder","params":{"peak":0}})).is_err());}
#[test]fn bound_helper_rejects_unknown_param(){use kimo_core::commands::{Session,dispatch};use serde_json::json;let mut s=Session::new();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","start":0,"duration":1})).unwrap()["clip_id"].clone();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true}})).unwrap();assert!(dispatch(&mut s,"add_managed_linear_effect",&json!({"clip_id":c,"kind":"linear_grade","params":{"exposurre":3}})).is_err());assert_eq!(s.project.find_clip(c.as_str().unwrap()).unwrap().effects.len(),0);}
